<?php require_once APP_ROOT.'/app/views/admin/tv3_ui.php';tv3_start('Ảnh: '.($product['name']??''));?><form method="post" action="admin_tv3.php?route=admin/products/images/add"><?php tv3_csrf($csrf)?><input type="hidden" name="product_id" value="<?=e($product['id'])?>"><label>URL ảnh http(s) <input type="url" name="image_path" maxlength="500" required style="width:80%"></label><label>Màu <select name="color_id"><option value="">Ảnh chung</option><?php foreach($colors as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach?></select></label><label><input type="checkbox" name="is_main" value="1"> Đặt làm ảnh chính</label><button>Thêm ảnh</button></form><table><tr><th>Ảnh</th><th>URL</th><th>Màu ID</th><th>Ảnh chính</th><th>Sửa / xóa (C10)</th></tr><?php foreach($images as $i):?><tr><td><img src="<?=e($i['image_path'])?>" alt="Ảnh sản phẩm" width="90" loading="lazy"></td><td><?=e($i['image_path'])?></td><td><?=e($i['color_id']??'Chung')?></td><td><?php if($i['is_main']):?>Có<?php else:?><form method="post" action="admin_tv3.php?route=admin/products/images/main"><?php tv3_csrf($csrf)?><input type="hidden" name="product_id" value="<?=e($product['id'])?>"><input type="hidden" name="image_id" value="<?=e($i['id'])?>"><button>Chọn ảnh chính</button></form><?php endif?></td><td><form method="post" action="admin_tv3.php?route=admin/products/images/update"><?php tv3_csrf($csrf)?><input type="hidden" name="product_id" value="<?=e($product['id'])?>"><input type="hidden" name="image_id" value="<?=e($i['id'])?>"><label>URL <input type="url" name="image_path" maxlength="500" required value="<?=e($i['image_path'])?>"></label><label>Màu <select name="color_id"><option value="">Ảnh chung</option><?php foreach($colors as $c):?><option value="<?=e($c['id'])?>" <?=((int)($i['color_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><label>Thứ tự <input type="number" name="sort_order" min="0" max="1000000" value="<?=e($i['sort_order'])?>"></label><button>Lưu ảnh</button></form><form method="post" action="admin_tv3.php?route=admin/products/images/delete" onsubmit="return confirm('Xóa ảnh này?')"><?php tv3_csrf($csrf)?><input type="hidden" name="product_id" value="<?=e($product['id'])?>"><input type="hidden" name="image_id" value="<?=e($i['id'])?>"><button>Xóa ảnh</button></form></td></tr><?php endforeach?></table><?php tv3_end();?>